\version "2.27.2"

\paper {
  % Add space for instrument names
  indent = 33\mm
}

global = {
  \key c \major
  \time 4/4
}

bcMusic = \relative c {
  \global
  % Music follows here.

  c4 c4 e4 d4 c4 g4 c4 c4
}

bcFigures = \figuremode {
  \global
  \override Staff.BassFigureAlignmentPositioning.direction = #DOWN
  % Figures follow here.

  <5>4 \skip4 \skip4 <6>4 \skip4 \skip4 <3>4 \skip4
}

\score {
  <<
    \new Staff \with {
      instrumentName = "Basso continuo"
      midiInstrument = "cello"
    } { \clef bass \bcMusic }
    \new FiguredBass \bcFigures
  >>
  \layout { }
  \midi {
    \tempo 4=100
  }
}

