}

rightOne = \relative c'' {
  \global
  % Music follows here.

  c4 c4 e4 d4 c4 g4 c4 c4
}

rightTwo = \relative c'' {
  \global
  % Music follows here.

  c4 c4 e4 d4 c4 g4 c4 c4
}

dynamics = {
  \global
  % Dynamics follow here.

}

leftOne = \relative c' {
  \global
  % Music follows here.

  c4 c4 e4 d4 c4 g4 c4 c4
}

leftTwo = \relative c' {
  \global
  % Music follows here.

  c4 c4 e4 d4 c4 g4 c4 c4
}

leftThree = \relative c' {
  \global
  % Music follows here.

  c4 c4 e4 d4 c4 g4 c4 c4
}

\score {
  \new PianoStaff \with {
    instrumentName = "Piano"
  } <<
    \new Staff = "right" \with {
      midiInstrument = "acoustic grand"
    } << \rightOne \\ \rightTwo >>
    \new Dynamics \dynamics
    \new Staff = "left" \with {
      midiInstrument = "acoustic grand"
    } { \clef bass << \leftOne \\ \leftTwo \\ \leftThree >> }
  >>
  \layout { }
  \midi {
    \tempo 4=100
  }
