}

verse = \lyricmode {
  % Lyrics follow here.

  ha ha ha ha ha ha ha ha
}

rehearsalMidi = #
(define-music-function
(parser location name midiInstrument lyrics) (string? string? ly:music?)
#{
  \unfoldRepeats <<
    \new Staff = "soprano" \new Voice = "soprano" { \soprano }
    \new Staff = "alto" \new Voice = "alto" { \alto }
