      \set Staff.midiMinimumVolume = #0.8
      \set Staff.midiMaximumVolume = #1.0
      \set Staff.midiInstrument = $midiInstrument
    }
    \new Lyrics \with {
      alignBelowContext = $name
    } \lyricsto $name $lyrics
  >>
#})

